def NetworkPositiveStatement : Prop :=
  ∀ G : Finset Plane, ∀ τ : PinAssignment G, ∀ D : Network G,
    D.Auxiliary → ∀ b : Bool, 0 < D.partition τ b (fun _ => 1)

def FreeRemovedPairStatement : Prop :=
  ∀ a : Departure, ∀ f ∈ a.D.presentNeighbours a.y, ∀ g ∈ a.D.presentNeighbours a.y, f ≠ g →
    0 ≤ removedPairMean a.D a.τ false a.y f g

def LogMeanMonotoneStatement : Prop :=
  ∀ x x' y y' : ℝ, 0 < x → x ≤ x' → 0 < y → y ≤ y' →
    logarithmicMean x y ≤ logarithmicMean x' y'

def DStepTrivialStatement : Prop :=
  ∀ a : Departure, a.D.status a.y = .D →
    stepRatio a.D a.τ true a.y a.o = 1 ∧ stepRatio a.D a.τ false a.y a.o = 1

def OneStepTrivialStatement : Prop :=
  ∀ a : Departure, a.D.status a.y = .U → (a.D.presentNeighbours a.y).card = 1 →
    stepRatio a.D a.τ true a.y a.o = 1 ∧ stepRatio a.D a.τ false a.y a.o = 1

def ReciprocalIntegralStatement : Prop :=
  ∀ x y : ℝ, 0 < x → 0 < y →
    (logarithmicMean x y)⁻¹ = ∫ t in (0 : ℝ)..1, ((1 - t) * x + t * y)⁻¹

def TypedCrudeRowsStatement : Prop :=
  ∀ straight : Bool, alphaBound straight ≤ 18094 / 100000 ∧
    betaBound straight ≤ 36751 / 100000 ∧ betaPrimeBound straight ≤ 36751 / 100000

def BetaPrimeAnalyticStatement : Prop :=
  ∀ c It I₀ : ℝ, 0 < c → c ≤ It → 1 ≤ I₀ →
    1 / (3 * logarithmicMean It I₀) ≤ reciprocalLogMean c / 3

def KernelOrderingStatement : Prop :=
  ∀ n : ℕ, ∀ w : DirectionWord n,
    (kernelOrdering w).Perm (firstVisitList w) ∧ (kernelOrdering w).Nodup

def ShiftGeometryStatement : Prop :=
  ∀ n : ℕ, ∀ X : PairType, ∀ w : DirectionWord n, ClosedTrail X w →
    ∀ i : Fin n, ∀ p ∈ responsePairs w i, (pairShift X p : ℝ) ≤ (n : ℝ) / 2 + 1

def KernelSupportStatement : Prop :=
  (∀ X Y : PairType, ∀ s : ℕ, kernelLengthCoefficient X Y s 0 = 0) ∧
  ∀ X Y : PairType, ∀ n s : ℕ, n + 1 < s → kernelLengthCoefficient X Y s n = 0

def KernelRegroupStatement : Prop :=
  ∀ θ : ℝ, 0 < θ → ∀ X Y : PairType,
    shiftedKernel θ X Y = ∑' n : ℕ, shiftedLength θ X Y n

def MajorantFiniteStatement : Prop :=
  ∀ CV q : ℝ, OpenTrailBound CV q → ∀ θ : ℝ, q^2 < θ → θ ≤ 1 →
    (∑' n : ℕ, ENNReal.ofReal (kernelMajorant CV q θ n)) ≠ ⊤

def ShiftedRowsRealStatement : Prop :=
  ∀ θ ρ : ℝ, 0 < θ → θ < 1 → 0 < ρ → ρ < 1 →
    Top.ShiftedWitness θ ρ → RenewalRows realKernel witnessReal θ ρ

def EnvelopeOrderStatement : Prop :=
  (∀ X : PairType, ∀ d : ℤ, d < 0 → responseEnvelope X d = responseEnvelope X 0) ∧
    ∀ X : PairType, Antitone (responseEnvelope X)

def ProtectedDistanceFiniteStatement : Prop :=
  ∀ G : Finset Plane, G.Nonempty → (protectedSites G).Nonempty ∧
    ∀ x : Plane, setDistance latticeDist x (↑(protectedSites G) : Set Plane) ≠ ⊤

def PairResponseSplitStatement : Prop :=
  ∀ p : PairData, p.u ∉ protectedSites p.G → p.v ∉ protectedSites p.G →
    p.response = firstTerm p + secondTerm p

def RenewalScalarLimitStatement : Prop :=
  ∀ x a b ρ : ℝ, 0 ≤ a → 0 ≤ b → 0 < ρ → ρ < 1 →
    (∀ k : ℕ, x ≤ a * ρ^k + b * ∑ j ∈ Finset.range k, ρ^j) → x ≤ b / (1 - ρ)

def BoundaryExampleCoveredStatementV2 : Prop :=
  AKLT.Defs.CoveredDepartureV2 (normalizeStart boundaryExampleD (0, 0) (-1, 0))
    (0, 0) .east .east
